from pathlib import Path
import hashlib,json,html,os,datetime,subprocess
root=Path(__file__).resolve().parents[1];out=root/'docs/audit';out.mkdir(exist_ok=True)
items=[]
for folder in ['docs/screenshots','docs/reference','target/temple-run/analysis','target/temple-run/web/public/assets','tools']:
 for p in sorted((root/folder).rglob('*')):
  if not p.is_file() or p.suffix.lower() not in ['.jpg','.jpeg','.png','.webp','.json','.asm','.glsl','.md','.txt','.obj','.py','.ts','.js','.log']:continue
  b=p.read_bytes();rel=p.relative_to(root).as_posix();image=p.suffix.lower() in ['.jpg','.jpeg','.png','.webp']
  group='复核脚本与测试源码' if folder=='tools' else '游戏素材（需核对来源）' if '/public/assets/'in rel else '视频参考' if rel.startswith('docs/screenshots/') or rel.startswith('docs/reference/') else 'APK/原规则取证' if '/native-'in rel or '/native/'in rel or p.suffix=='.asm' else '网页测试与现场'
  items.append(dict(path=rel,url=os.path.relpath(p,out).replace(os.sep,'/'),kind='图片' if image else '原始文件',group=group,bytes=len(b),sha256=hashlib.sha256(b).hexdigest()))
data=json.dumps(items,ensure_ascii=False).replace('<',r'\u003c')
counts={g:sum(x['group']==g for x in items)for g in sorted({x['group']for x in items})}
(out/'manifest.json').write_text(json.dumps({'generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'counts':counts,'items':items},ensure_ascii=False,indent=2)+'\n')
